def correct_bracketing(brackets: str) -> bool:
    stack = []
    for char in brackets:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if not stack or stack.pop() != '<':
                return False
    return len(stack) == 0

def circular_shift(x, shift):
    if shift > len(str(x)):
        return str(x)[::-1]

    shift %= len(str(x))
    return str(x)[-shift:] + str(x)[:-shift]

def smallest_change(arr):
    left, right = 0, len(arr) - 1
    changes = 0

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

def is_simple_power(x, n):
    if x == 1:
        return True
    if n <= 1 or x < n:
        return False
    while x % n == 0:
        x //= n
    return x == 1

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary = ""
    while decimal > 0:
        remainder = decimal % 2
        binary = str(remainder) + binary
        decimal //= 2

    return f"db{binary}db"

import math

def prime_length(string):
    length = len(string)
    if length <= 1:
        return False
    for i in range(2, int(math.sqrt(length)) + 1):
        if length % i == 0:
            return False
    return True

def encrypt(s):
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    shifted_alphabet = alphabet[2*2:] + alphabet[:2*2]
    result = ""
    for char in s:
        if char.isalpha():
            index = alphabet.index(char.lower())
            new_index = (index + 2*2) % 26
            result += shifted_alphabet[new_index].upper() if char.isupper() else shifted_alphabet[new_index]
        else:
            result += char
    return result

import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    max_prime = 0
    for num in lst:
        if num > max_prime and is_prime(num):
            max_prime = num
    return sum(int(digit) for digit in str(max_prime))

def by_length(arr):
    def num_to_word(n):
        return {
            1: 'One', 2: 'Two', 3: 'Three', 4: 'Four',
            5: 'Five', 6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine'
        }.get(n, '')

    # Filter and sort the array
    filtered_sorted_arr = sorted([num for num in arr if 1 <= num <= 9], reverse=True)

    # Convert numbers to words
    word_arr = [num_to_word(num) for num in filtered_sorted_arr]

    return word_arr

def move_one_ball(arr):
    if len(arr) == 0:
        return True

    # Check if the array is already sorted or has only one element
    if arr == sorted(arr) or len(arr) == 1:
        return True

    # Count the number of inversions (elements out of their correct order)
    inversion_count = sum(1 for i in range(len(arr)) if arr[i] > arr[(i + 1) % len(arr)])

    # If there's exactly one inversion, we can always make the array sorted by one right shift
    return inversion_count == 1

def reverse_delete(s, c):
    # Remove characters from s that are present in c
    filtered_s = ''.join([char for char in s if char not in c])

    # Check if the filtered string is a palindrome
    is_palindrome = filtered_s == filtered_s[::-1]

    return (filtered_s, is_palindrome)

import math

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return math.ceil(total_water / capacity)

def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    for i in range(len(word) - 2, -1, -1):
        if word[i] not in vowels and word[i + 1] in vowels:
            return word[i]
    return ''

import re

def valid_date(date):
    # Regular expression to match the date format mm-dd-yyyy
    pattern = r"^(0[1-9]|1[0-2])-([0-2][0-9]|3[01])-(\d{4})$"

    # Check if the date matches the pattern
    if re.match(pattern, date):
        # Extract month, day, and year from the date string
        month, day, year = map(int, date.split('-'))

        # Validate the month
        if month < 1 or month > 12:
            return False

        # Validate the day based on the month
        if month in [1, 3, 5, 7, 8, 10, 12]:
            if day < 1 or day > 31:
                return False
        elif month in [4, 6, 9, 11]:
            if day < 1 or day > 30:
                return False
        elif month == 2:
            if day < 1 or day > 29:
                return False

        # If all checks pass, the date is valid
        return True
    else:
        return False

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        if num == 0:
            return 0

        sign_product *= (-1 if num < 0 else 1)
        magnitude_sum += abs(num)

    return magnitude_sum * sign_product

def digits(n):
    product = 1
    has_odd_digit = False
    while n > 0:
        digit = n % 10
        if digit % 2 != 0:
            product *= digit
            has_odd_digit = True
        n //= 10
    return product if has_odd_digit else 0

def can_arrange(arr):
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            return i
    return -1
